DO $$
DECLARE
  missing_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO missing_count
  FROM (
    VALUES
      ('puglia'), ('sicily'), ('south_tyrol'), ('provence'), ('catalonia'),
      ('alentejo'), ('istria'), ('pomurska'), ('southeast_slovenia'),
      ('central_slovenia'), ('goriska'), ('trondelag'), ('more_og_romsdal'),
      ('buskerud'), ('vestland')
